import{_ as e}from"./chunks/prontera-church.uydloSKv.js";import{_ as r,o as a,c as o,ag as d}from"./chunks/framework.DGzMGr_a.js";const P=JSON.parse('{"title":"系统配置要求与安装指南","description":"RO3 PC端和移动端系统配置要求、预注册方法、安装下载完整指南。","frontmatter":{"title":"系统配置要求与安装指南","description":"RO3 PC端和移动端系统配置要求、预注册方法、安装下载完整指南。","lastUpdated":true},"headers":[],"relativePath":"guide/requirements.md","filePath":"guide/requirements.md","lastUpdated":1780230058000}'),i={name:"guide/requirements.md"};function n(l,t,s,h,g,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="系统配置要求与安装指南" tabindex="-1">系统配置要求与安装指南 <a class="header-anchor" href="#系统配置要求与安装指南" aria-label="Permalink to &quot;系统配置要求与安装指南&quot;">​</a></h1><p><img src="'+e+'" alt="RO3 游戏截图"></p><h2 id="pc-端配置要求" tabindex="-1">PC 端配置要求 <a class="header-anchor" href="#pc-端配置要求" aria-label="Permalink to &quot;PC 端配置要求&quot;">​</a></h2><p>根据2025年8月Pioneer Test期间公布的信息，RO3的PC端配置要求如下：</p><h3 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>Intel</th><th>AMD</th></tr></thead><tbody><tr><td><strong>CPU</strong></td><td>Intel Core i5-13420H</td><td>AMD Ryzen 5 7535HS / Ryzen 5 5600H</td></tr><tr><td><strong>内存</strong></td><td>16GB DDR4 3200MHz</td><td>16GB DDR4 3200MHz</td></tr><tr><td><strong>存储</strong></td><td>1TB NVMe SSD</td><td>1TB NVMe SSD</td></tr><tr><td><strong>显卡</strong></td><td>NVIDIA GTX 1050 Ti</td><td>NVIDIA GTX 1050 Ti / AMD Radeon RX 6400</td></tr></tbody></table><h3 id="最低配置" tabindex="-1">最低配置 <a class="header-anchor" href="#最低配置" aria-label="Permalink to &quot;最低配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>Intel</th><th>AMD</th></tr></thead><tbody><tr><td><strong>CPU</strong></td><td>Intel Core i3-12100 (4核/8线程)</td><td>AMD Ryzen 3 5300G / Ryzen 5 4600G</td></tr><tr><td><strong>内存</strong></td><td>8GB DDR4 3200MHz</td><td>8GB DDR4 3200MHz</td></tr><tr><td><strong>存储</strong></td><td>512GB NVMe SSD</td><td>512GB NVMe SSD</td></tr><tr><td><strong>显卡</strong></td><td>Intel UHD 730</td><td>Radeon Vega6/Vega7</td></tr></tbody></table><h3 id="硬盘空间" tabindex="-1">硬盘空间 <a class="header-anchor" href="#硬盘空间" aria-label="Permalink to &quot;硬盘空间&quot;">​</a></h3><ul><li><strong>客户端大小</strong>：约10-20GB（预计正式版）</li><li><strong>建议预留</strong>：至少30GB可用空间</li></ul><h2 id="移动端配置要求" tabindex="-1">移动端配置要求 <a class="header-anchor" href="#移动端配置要求" aria-label="Permalink to &quot;移动端配置要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>最低要求</th><th>推荐配置</th></tr></thead><tbody><tr><td><strong>iOS</strong></td><td>iOS 11.0+，iPhone 8 或更新机型</td><td>iPhone 12 或更新机型</td></tr><tr><td><strong>Android</strong></td><td>骁龙845 或同等处理器，4GB+ 内存</td><td>骁龙8 Gen1 或同等，8GB+ 内存</td></tr></tbody></table><blockquote><p><strong>注意</strong>：Pioneer Test期间仅开放PC平台，移动端将在后续测试中逐步开放。</p></blockquote><h2 id="预注册方法" tabindex="-1">预注册方法 <a class="header-anchor" href="#预注册方法" aria-label="Permalink to &quot;预注册方法&quot;">​</a></h2><p>目前全球服官网已开放预注册：</p><ol><li>访问 <a href="https://ro3global.com/" target="_blank" rel="noreferrer">RO3 全球官网</a></li><li>点击「Pre-register」或「事前预约」</li><li>填写邮箱地址</li><li>关注官方Discord和Facebook获取测试资格通知</li></ol><h2 id="pc-版安装指引-参考pioneer-test流程" tabindex="-1">PC 版安装指引（参考Pioneer Test流程） <a class="header-anchor" href="#pc-版安装指引-参考pioneer-test流程" aria-label="Permalink to &quot;PC 版安装指引（参考Pioneer Test流程）&quot;">​</a></h2><ol><li>从官网下载启动器</li><li>安装启动器并登录账号</li><li>下载游戏客户端（约15-20GB）</li><li>启动游戏，创建角色</li></ol><h2 id="账号相关" tabindex="-1">账号相关 <a class="header-anchor" href="#账号相关" aria-label="Permalink to &quot;账号相关&quot;">​</a></h2><ul><li><strong>最大角色数</strong>：每个账号最多6个角色（Pioneer Test数据）</li><li><strong>账号类型</strong>：全球服使用Gravity账号</li><li><strong>国服</strong>：使用上海热血网络账号体系（后续公布）</li><li><strong>日服</strong>：使用GungHo账号体系</li></ul><h2 id="网络要求" tabindex="-1">网络要求 <a class="header-anchor" href="#网络要求" aria-label="Permalink to &quot;网络要求&quot;">​</a></h2><ul><li><strong>全球服</strong>：需要稳定的网络连接，建议使用有线网络或5G/Wi-Fi 6</li><li><strong>国服</strong>：国内直连，无需加速器</li><li><strong>延迟参考</strong>：推荐延迟 &lt; 100ms</li></ul>',22)])])}const p=r(i,[["render",n]]);export{P as __pageData,p as default};
